package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the note threshold just saved (blank: none), even when it is the one the sheet had; nothing when it was left as it is. */
public class AuditNoteThreshold {
    public void audit(@Val NoteThreshold threshold, @Val Sheet sheet, @RequestParam("user") String user, Audit audit) {
        if (!threshold.given()) {
            return;
        }
        audit.record("SETTING_CHANGED sheet=" + sheet.id() + " by=" + user + " key=note-threshold value="
                + (threshold.value() == null ? "" : threshold.value().toPlainString())
                + DatedSettings.auditFrom(threshold.from()));
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated note threshold with two decimals; {@code value} null: none. {@code given} false: left as it is. {@code from} null: none typed, the sheet's today. */
public record NoteThreshold(boolean given, BigDecimal value, LocalDate from) {
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

public class SaveNoteThreshold {
    public void save(@Val NoteThreshold threshold, @Val Sheet sheet, SettingRepository repository) {
        if (threshold.given()) {
            repository.saveDated(sheet.id(), DatedSettings.NOTE_THRESHOLD,
                    DatedSettings.fromOr(threshold.from(), sheet.today()),
                    threshold.value() == null ? null : threshold.value().toPlainString());
        }
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.constraints.Size;
import java.util.Map;

/**
 * The settings as the form submits them; a setting left out (null) is left as it is. The clerk limit has two
 * decimals at most (blank: no limit); the floor has two decimals at most (blank: back to 1.00); the terms are
 * whole days, 0 or more (blank: back to 14); the late percent has two decimals at most (blank: back to 0.00); the policy date is
 * yyyy-MM-dd (blank: the sheet's today); the period numbering from date is yyyy-MM-dd (blank: off); the entry date is yyyy-MM-dd (blank: off); the cap has two decimals at most (blank: no cap); the proof threshold has two decimals at most (blank: none); the note threshold has two decimals at most (blank: none). The grade terms are
 * whole days, 0 or more, by grade, each only for a grade it carries (blank: none of its own, the sheet's terms).
 * The clerk limit, floor, terms, late percent, cap, proof threshold, note threshold and each grade's terms are recorded from their from-date, yyyy-MM-dd
 * (left out or blank: the sheet's today). The permissions are, by action (open, settle, void, reassign, close, reopen),
 * the roles allowed it, comma separated (blank: the standing rule); they are not dated. The grace days are whole days,
 * 0 or more (blank: off); they are not dated. The grade grace days are whole days, 0 or more, by grade, each only for a
 * grade it carries (blank: none), recorded from their from-date by grade (left out or blank: the sheet's today). The pot has two decimals at most (blank: none); it is not dated. The parent is a sheet id (blank: none); it is not dated. The fiscal start month is 1 to 12 (blank: back to 1); it is not dated. The alert threshold has two decimals at most (blank: off); it is not dated. The grade
 * proof thresholds have two decimals at most, by grade, each only for a grade it carries (blank: none, the sheet's), recorded
 * from their from-date by grade (left out or blank: the sheet's today). The rounding mode is half-up or half-even (blank: none,
 * the policy date decides), recorded from its from-date (left out or blank: the sheet's today).
 */
public record SettingsRequest(@Size(max = 30) String clerkLimit, @Size(max = 30) String floor, @Size(max = 30) String terms,
        @Size(max = 30) String latePct, @Size(max = 30) String policyDate, @Size(max = 30) String periodNumberingFrom, @Size(max = 30) String entryDate, @Size(max = 30) String cap,
        @Size(max = 30) String proofThreshold, @Size(max = 30) String noteThreshold,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeTerms,
        @Size(max = 30) String clerkLimitFrom, @Size(max = 30) String floorFrom, @Size(max = 30) String termsFrom,
        @Size(max = 30) String latePctFrom, @Size(max = 30) String capFrom, @Size(max = 30) String proofThresholdFrom,
        @Size(max = 30) String noteThresholdFrom,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeTermsFrom,
        @Size(max = 10) Map<String, @Size(max = 100) String> permissions, @Size(max = 30) String graceDays,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeGrace,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeGraceFrom,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeProofThreshold,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeProofThresholdFrom,
        @Size(max = 30) String pot, @Size(max = 100) String parent, @Size(max = 30) String fiscalStartMonth,
        @Size(max = 30) String alertThreshold, @Size(max = 30) String rounding, @Size(max = 30) String roundingFrom) {
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The settings as the screen reads them: the clerk limit (null: no limit), the floor, the terms in days, the terms set for
 * each grade that has its own (by grade), the late percent, the policy date ("": blank, the sheet's today), the period
 * numbering from date ("": off), the entry date ("": off), the cap ("": none), the proof threshold ("": none), the note threshold ("": none) — the dated ones as in force on the sheet's today — each role given,
 * by user name, the permission matrix (by action, the roles allowed it; "": blank, the standing rule), and every dated value recorded, by key, oldest from-date first (value "": blank), the grace days ("": off), the steward role delegated, in the order made, the pot ("": none), the parent sheet id ("": none) the fiscal year start month (1 to 12), the alert threshold ("": off) and the rounding mode in force on the sheet's today ("": none).
 */
public record SettingsResponse(String clerkLimit, String floor, int terms, Map<String, Integer> gradeTerms, String latePct, String policyDate, String periodNumberingFrom, String entryDate, String cap, String proofThreshold, String noteThreshold, List<RoleResponse> roles,
        Map<String, List<FromValueResponse>> history, Map<String, String> permissions, String graceDays,
        List<DelegationResponse> delegations, String pot, String parent, String fiscalStartMonth, String alertThreshold, String rounding) {

    public record RoleResponse(String user, String role) {
    }

    public record DelegationResponse(String user, String from, String to, String by) {
    }

    public record FromValueResponse(String from, String value) {
    }

    public static SettingsResponse from(Settings settings) {
        BigDecimal noteThreshold = settings.dated().noteThresholdOn(settings.today());
        String rounding = settings.dated().roundingOn(settings.today());
        Map<String, List<FromValueResponse>> history = new LinkedHashMap<>();
        settings.dated().history().forEach((key, values) -> history.put(key, values.stream()
                .map((v) -> new FromValueResponse(v.from().toString(), v.value() == null ? "" : v.value())).toList()));
        return new SettingsResponse(
                settings.clerkLimit() == null ? null : settings.clerkLimit().toPlainString(),
                settings.floor().toPlainString(),
                settings.terms(),
                settings.gradeTerms(),
                settings.latePct().toPlainString(),
                settings.policyDate() == null ? "" : settings.policyDate().toString(),
                settings.periodNumberingFrom() == null ? "" : settings.periodNumberingFrom().toString(),
                settings.entryDate() == null ? "" : settings.entryDate().toString(),
                settings.cap() == null ? "" : settings.cap().toPlainString(),
                settings.proofThreshold() == null ? "" : settings.proofThreshold().toPlainString(),
                noteThreshold == null ? "" : noteThreshold.toPlainString(),
                settings.roles().stream().map((r) -> new RoleResponse(r.user(), r.role().label())).toList(),
                history,
                settings.permissions().entries(),
                settings.graceDays() == null ? "" : settings.graceDays().toString(),
                settings.delegations().stream().map((d) -> new DelegationResponse(d.user(), d.from().toString(),
                        d.to().toString(), d.by())).toList(),
                settings.pot() == null ? "" : settings.pot().toPlainString(),
                settings.parent() == null ? "" : settings.parent(),
                Integer.toString(settings.fiscalStartMonth()),
                settings.alertThreshold() == null ? "" : settings.alertThreshold().toPlainString(),
                rounding == null ? "" : rounding);
    }
}
