import { useAliases } from '../aliases/aliases';
import type { Alias } from '../aliases/aliases';
import { useClaims } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { personOverdue } from '../overdue/overdue';
import { liveHolds, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { personDue, trimmedTotal, useRates } from '../rates/rates';
import type { Rate } from '../rates/rates';
import { useDueRules } from '../settings/settings';
import type { DueRules } from '../settings/settings';
import { useCurrentUser } from '../session/session';

/** The statuses counted, as in the summary; one no claim reaches yet still shows, as 0. */
const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const;

/** A sheet's due-total and overdue-total as its header shows them. */
export function sheetTotals(people: Person[], claims: Claim[], rates: Rate[], rules: DueRules): { due: string; overdue: string } {
  const mine = (id: number) => claims.filter((c) => c.personId === id);
  const dues = people.map((p) => personDue(mine(p.id), rates, p.grades, liveHolds(p, rules.today), rules));
  const overdue = people.map((p) => personOverdue(mine(p.id), rates, p.grades, liveHolds(p, rules.today), rules).total);
  return { due: trimmedTotal(dues), overdue: trimmedTotal(overdue) };
}

/** A name as names are compared: trimmed, ignoring case. */
const nameKey = (name: string) => name.trim().toLowerCase();

/** The person on the sheet with the user's name, by name or alias, if any. */
export function personNamed(people: Person[], aliases: Alias[], user: string): Person | undefined {
  const key = nameKey(user);
  if (!key) return undefined;
  return (
    people.find((p) => nameKey(p.name) === key) ??
    people.find((p) => aliases.some((a) => a.personId === p.id && nameKey(a.alias) === key))
  );
}

// The sheet's counters, always in the header: everyone on it (retired people included), its claims per
// status, its due-total and overdue-total, and the signed-in user's own (blank when no one on it has their name) — each worked out exactly as the figure it repeats.
export function HeaderCounters() {
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const aliases = useAliases().data ?? [];
  const [user] = useCurrentUser();

  const me = personNamed(people, aliases, user ?? '');
  const mine = me ? claims.filter((c) => c.personId === me.id) : [];
  const myDue = me ? personDue(mine, rates, me.grades, liveHolds(me, rules.today), rules) : '';
  const myOverdue = me ? personOverdue(mine, rates, me.grades, liveHolds(me, rules.today), rules).total : '';
  const totals = sheetTotals(people, claims, rates, rules);
  return (
    <p data-testid="header-counters">
      People: <strong data-testid="header-people-count">{people.length}</strong>
      {STATUSES.map((s) => (
        <span key={s}>
          {' · '}
          {s}: <strong data-testid={`header-claims-${s}-count`}>{claims.filter((c) => c.status === s).length}</strong>
        </span>
      ))}
      {' · '}Due: <strong data-testid="header-due-total">{totals.due}</strong>
      {' · '}Overdue: <strong data-testid="header-overdue-total">{totals.overdue}</strong>
      {' · '}Mine: <strong data-testid="my-due-total">{myDue}</strong>
      {' / '}<strong data-testid="my-overdue-total">{myOverdue}</strong>
    </p>
  );
}
import { isActive } from '../active/active';
import { useClaims } from '../claims/claims';
import { GRADES, liveHolds, usePeople } from '../people/people';
import { periodDue, usePeriods } from '../periods/periods';
import { personDue, total, useRates } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useDueRules } from '../settings/settings';
import { useVoidReasons } from '../voidreasons/voidReasons';

/** The statuses the summary counts claims by; one no claim reaches yet still shows, as 0. */
const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const;

// The sheet at a glance, worked out from the same figures the list shows. Per grade: the people on it
// today (retired people left out), their due-totals added up (skipping n/a) and how many of them are active. Per period: its
// due-total and its change from the period before it by start date (none for the earliest). Per status: how many claims have it. Per void reason on the list: how many VOID claims were voided with it.
export function Summary() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const periods = usePeriods().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const voidReasons = useVoidReasons().data ?? [];

  if (!user || !sheet) return null;

  const current = people.filter((p) => !p.retired);
  const periodDues = new Map(periods.map((p) => [p.name, periodDue(p, claims, people, rates, rules)]));
  const byStart = [...periods].sort((a, b) => a.from.localeCompare(b.from));
  const periodChange = new Map(
    byStart.map((p, i) => [
      p.name,
      i === 0 ? '' : (cents(periodDues.get(p.name)!) - cents(periodDues.get(byStart[i - 1].name)!)) / 100,
    ]),
  );
  return (
    <section data-testid="summary">
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due total</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const on = current.filter((p) => p.grade === g);
            const dues = on.map((p) =>
              personDue(claims.filter((c) => c.personId === p.id), rates, p.grades, liveHolds(p, rules.today), rules),
            );
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{on.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>{total(dues)}</td>
                <td data-testid={`summary-grade-${g}-active`}>
                  {on.filter((p) => isActive(claims.filter((c) => c.personId === p.id), liveHolds(p, rules.today), rules.today)).length}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due total</th>
            <th>Change</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{periodDues.get(p.name)}</td>
              <td data-testid={`summary-period-${p.name}-change`}>{formatChange(periodChange.get(p.name))}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{claims.filter((c) => c.status === s).length}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Void reason</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {voidReasons.map((r) => (
            <tr key={r}>
              <td>{r}</td>
              <td data-testid={`summary-void-${r}-count`}>
                {claims.filter((c) => c.status === 'VOID' && c.voidReason === r).length}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

/** A two-decimal value as whole hundredths, exactly. */
const cents = (value: string) => Math.round(Number(value) * 100);

/** A change in due-total, two decimals with a minus sign when lower; nothing for the earliest period. */
function formatChange(change: number | string | undefined): string {
  return typeof change === 'number' ? (change === 0 ? '0.00' : change.toFixed(2)) : '';
}
import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { usePeople } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { claimsKey, useClaims } from './claims';
import type { Claim } from './claims';
import { useSelectedClaims } from './selection';
import { useOneAtATime } from '../../query/useOneAtATime';

// Opens every ticked claim, one after another in list order (people in their order, each one's
// claims newest first), so they are numbered in that order. Each goes through the claim's own open
// action: one the server refuses is left as it is and counted as refused.
export function BulkOpen() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const [selected, , clear] = useSelectedClaims();
  const [result, setResult] = useState<{ opened: number; refused: number } | undefined>(undefined);
  const [busy, setBusy] = useState(false);
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  if (!user || !sheet) return null;

  const run = async () => {
    setResult(undefined);
    setBusy(true);
    const ordered = people.flatMap((p) => claims.filter((c) => c.personId === p.id && selected.has(c.id)));
    let opened = 0;
    let refused = 0;
    try {
      for (const c of ordered) {
        try {
          await postJson<Claim>(
            `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/open?user=${encodeURIComponent(user)}`,
            {},
          );
          opened++;
        } catch {
          refused++;
        }
      }
      // A ticked claim no longer listed (gone from the sheet) cannot be opened.
      refused += selected.size - ordered.length;
      clear();
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    } finally {
      setBusy(false);
      setResult({ opened, refused });
    }
  };

  return (
    <p>
      <button type="button" data-testid="bulk-open" disabled={busy} onClick={() => once(run)}>
        Open selected claims
      </button>
      {result && (
        <>
          {' '}
          Opened <span data-testid="bulk-opened">{result.opened}</span>, refused{' '}
          <span data-testid="bulk-refused">{result.refused}</span>
        </>
      )}
    </p>
  );
}

